import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  AlertTriangle, Archive, ArrowLeft, ArrowRight, BadgePercent, BarChart3, Check,
  CheckCircle2, CircleDollarSign, Clock3, Copy, Eye, Gift, Megaphone, Monitor,
  MoreHorizontal, Pause, Pencil, Plus, RefreshCw, RotateCcw, Rocket, Smartphone,
  Sparkles, Target, Users, WandSparkles, XCircle,
} from 'lucide-react';
import ImageUploader from '../../components/admin/ImageUploader';
import PageHeader from '../../components/admin/PageHeader';
import ConfirmModal from '../../components/admin/ConfirmModal';
import PageState from '../../components/ui/PageState';
import api from '../../services/api';
import WorkflowSmartFill from '../../components/admin/WorkflowSmartFill';
import { useAuth } from '../../context/AuthContext';

const PRESETS = [
  { id: 'FIRST_ORDER', title: 'First order', note: 'Welcome new shoppers with a controlled introductory offer.', icon: Sparkles, defaults: { code: 'WELCOME15', customerSegment: 'NEW', firstOrderOnly: true, discountValue: 15, minOrderAmount: 999, maxDiscountAmount: 500, customerLimit: 1, endHours: 720, position: 'Home - Top' } },
  { id: 'FREE_SHIPPING', title: 'Free shipping', note: 'Remove delivery cost after a minimum cart value.', icon: Gift, defaults: { code: 'FREESHIP', activationMode: 'AUTOMATIC', benefitType: 'FREE_SHIPPING', discountValue: 0, minOrderAmount: 999, maxDiscountAmount: 150, usageLimit: 1000, totalBudget: 100000, endHours: 720, position: 'Cart - Bottom', destinationType: 'COUPON' } },
  { id: 'FESTIVAL', title: 'Festival sale', note: 'Schedule a rich storefront edit for a seasonal moment.', icon: Megaphone, defaults: { code: 'FESTIVE20', discountValue: 20, maxDiscountAmount: 1000, usageLimit: 1000, totalBudget: 100000, endHours: 168, position: 'Home - Middle', destinationType: 'COLLECTION', destinationValue: 'Festival Edit' } },
  { id: 'FLASH', title: 'Flash sale', note: 'Run an urgent offer with a mandatory closing time.', icon: Clock3, defaults: { code: 'FLASH20', discountValue: 20, maxDiscountAmount: 750, usageLimit: 200, totalBudget: 50000, position: 'Offer Strip', startNow: true, endHours: 24 } },
  { id: 'CATEGORY', title: 'Category offer', note: 'Discount only the categories you select.', icon: Target, defaults: { code: 'CATEGORY15', discountValue: 15, maxDiscountAmount: 750, usageLimit: 500, totalBudget: 50000, endHours: 168, position: 'Category - Featured', destinationType: 'CATEGORY' } },
  { id: 'BUY_GET', title: 'Buy X, get Y', note: 'Reward quantity while keeping products and limits explicit.', icon: BadgePercent, defaults: { code: 'BUY2GET1', benefitType: 'BUY_X_GET_Y', discountValue: 0, buyQuantity: 2, getQuantity: 1, usageLimit: 500, totalBudget: 75000, endHours: 168 } },
  { id: 'REPEAT', title: 'Repeat customers', note: 'Bring existing customers back with a private offer.', icon: Users, defaults: { code: 'COMEBACK15', customerSegment: 'REPEAT', minimumPriorOrders: 1, isPublic: false, discountValue: 15, maxDiscountAmount: 750, usageLimit: 500, totalBudget: 50000, endHours: 336 } },
  { id: 'VIP', title: 'VIP reward', note: 'Create a private benefit for your highest-value customers.', icon: CheckCircle2, defaults: { code: 'VIP20', customerSegment: 'VIP', minimumPriorOrders: 5, minimumLifetimeSpend: 25000, isPublic: false, discountValue: 20, maxDiscountAmount: 1500, usageLimit: 200, totalBudget: 75000, endHours: 720 } },
];
const FILTERS = ['ALL', 'DRAFT', 'SCHEDULED', 'LIVE', 'PAUSED', 'ENDED', 'FAILED', 'ARCHIVED'];
const STEPS = ['Goal', 'Audience', 'Offer', 'Creative', 'Schedule', 'Review'];
const STORAGE_KEY = 'samira_campaign_draft_v2';

export function buildCampaignDraftStorageKey(user = {}, storeId = '') {
  const account = user._id || user.id || user.phone || 'anonymous';
  const mode = user.activeMode || 'admin';
  return `${STORAGE_KEY}:${account}:${mode}:${storeId || 'default'}`;
}

function activeStoreScope(user) {
  try {
    if (user?.activeMode === 'seller') return sessionStorage.getItem('samira_seller_store_id') || user?.stores?.[0]?.id || '';
    return new URLSearchParams(window.location.search).get('storeId') || user?.storeId || '';
  } catch { return user?.storeId || ''; }
}

function initialForm(preset = 'FESTIVAL') {
  const selected = PRESETS.find((item) => item.id === preset) || PRESETS[2];
  const start = selected.defaults.startNow ? localDateTime(new Date()) : '';
  const end = selected.defaults.endHours ? localDateTime(new Date(Date.now() + selected.defaults.endHours * 3600000)) : '';
  return {
    idempotencyKey: `campaign-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    preset: selected.id, name: selected.title, startsAt: start, endsAt: end, timezone: 'Asia/Kolkata', revision: 0,
    offer: {
      code: selected.defaults.code, activationMode: selected.defaults.activationMode || 'CODE', benefitType: selected.defaults.benefitType || 'DISCOUNT',
      type: 'Percentage', discountValue: selected.defaults.discountValue ?? 10, buyQuantity: selected.defaults.buyQuantity || 2,
      getQuantity: selected.defaults.getQuantity || 1, minOrderAmount: selected.defaults.minOrderAmount || 0,
      minItemQuantity: 0, maxDiscountAmount: selected.defaults.maxDiscountAmount || 0, usageLimit: selected.defaults.usageLimit || 0, customerLimit: selected.defaults.customerLimit ?? 1, totalBudget: selected.defaults.totalBudget || 0,
      customerSegment: selected.defaults.customerSegment || 'ALL', firstOrderOnly: Boolean(selected.defaults.firstOrderOnly),
      minimumPriorOrders: selected.defaults.minimumPriorOrders || 0, minimumLifetimeSpend: selected.defaults.minimumLifetimeSpend || 0, inactiveDays: 90,
      stackingMode: 'ALLOW_PRODUCT_OFFERS', scopeMatchMode: 'ANY', minimumRequirementBasis: 'CART',
      restoreOnFullRefund: false, isPublic: selected.defaults.isPublic ?? true, applicableProducts: [], applicableCategories: [],
      applicableCustomers: [], applicablePincodes: [], applicablePaymentMethods: [], salesChannels: ['STOREFRONT'],
    },
    creative: {
      title: selected.title, subtitle: '', buttonText: 'Shop now', image: '', tabletImage: '', mobileImage: '', altText: '',
      focalPoint: 'center', type: ['FESTIVAL', 'FLASH'].includes(selected.id) ? 'Sale' : 'Offer',
      position: selected.defaults.position || 'Home - Middle', destinationType: selected.defaults.destinationType || 'CUSTOM',
      destinationValue: selected.defaults.destinationValue || '', link: '/products', displayOrder: 0,
    },
  };
}

export default function CampaignBuilder() {
  const { user, notify } = useAuth();
  const base = user?.activeMode === 'seller' ? '/seller' : '/admin';
  const storageKey = buildCampaignDraftStorageKey(user, activeStoreScope(user));
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState('ALL');
  const [range, setRange] = useState('30');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [editor, setEditor] = useState(null);
  const [step, setStep] = useState(0);
  const [saving, setSaving] = useState(false);
  const [actionId, setActionId] = useState('');
  const [confirm, setConfirm] = useState(null);
  const [options, setOptions] = useState({ PRODUCT: [], CATEGORY: [], CUSTOMER: [] });
  const [preview, setPreview] = useState('desktop');
  const [draftRestored, setDraftRestored] = useState(false);
  const [insights, setInsights] = useState(null);
  const [insightsLoading, setInsightsLoading] = useState(false);
  const [compareCampaigns, setCompareCampaigns] = useState([]);
  const [compareOpen, setCompareOpen] = useState(false);

  const load = useCallback(async ({ quiet = false } = {}) => {
    quiet ? setRefreshing(true) : setLoading(true); setError('');
    try {
      const query = new URLSearchParams({ page: String(page), limit: '12', range, state: filter });
      if (search.trim()) query.set('search', search.trim());
      setData(await api.get(`${base}/campaigns?${query}`, { silent: quiet }));
    } catch (requestError) { setError(requestError.message || 'Campaigns could not be loaded.'); }
    finally { setLoading(false); setRefreshing(false); }
  }, [base, filter, page, range, search]);

  useEffect(() => { const timer = setTimeout(() => load(), search ? 300 : 0); return () => clearTimeout(timer); }, [load, search]);

  useEffect(() => {
    if (!editor) return undefined;
    const selected = { PRODUCT: editor.offer.applicableProducts, CATEGORY: editor.offer.applicableCategories, CUSTOMER: editor.offer.applicableCustomers };
    let active = true;
    Promise.all(Object.keys(selected).map(async (type) => {
      const params = new URLSearchParams({ type, limit: '100' });
      if (selected[type]?.length) params.set('selected', selected[type].join(','));
      const response = await api.get(`${base}/coupons/options?${params}`, { silent: true });
      return [type, response.items || []];
    })).then((rows) => { if (active) setOptions(Object.fromEntries(rows)); }).catch((requestError) => { if (active) notify(requestError.message, 'error', 'Campaign targeting'); });
    return () => { active = false; };
  }, [base, editor?._id, editor?.idempotencyKey, notify]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (!editor || editor._id) return undefined;
    const timer = setTimeout(() => { try { localStorage.setItem(storageKey, JSON.stringify(editor)); } catch { /* storage may be unavailable */ } }, 350);
    return () => clearTimeout(timer);
  }, [editor, storageKey]);

  const stats = data?.stats || {};
  const openNew = (preset = 'FESTIVAL') => {
    let value = initialForm(preset); let restored = false;
    try {
      const stored = JSON.parse(localStorage.getItem(storageKey) || 'null');
      if (stored?.name && stored?.offer && stored?.creative) { value = stored; restored = true; }
    } catch { /* ignore an invalid local draft */ }
    setEditor(value); setDraftRestored(restored); setStep(0); setPreview('desktop');
  };
  const edit = (campaign) => { setEditor(toForm(campaign)); setDraftRestored(false); setStep(0); setPreview('desktop'); };
  const extend = (campaign) => { setEditor(toForm(campaign)); setDraftRestored(false); setStep(4); setPreview('desktop'); };
  const closeEditor = () => { setEditor(null); setDraftRestored(false); };
  const discardLocalDraft = () => { try { localStorage.removeItem(storageKey); } catch { /* ignore */ } setEditor(initialForm()); setDraftRestored(false); setStep(0); };
  const update = (field, value) => setEditor((current) => ({ ...current, [field]: value }));
  const updateOffer = (field, value) => setEditor((current) => ({ ...current, offer: { ...current.offer, [field]: value } }));
  const updateCreative = (field, value) => setEditor((current) => ({ ...current, creative: { ...current.creative, [field]: value } }));
  const choosePreset = (preset) => {
    const next = initialForm(preset.id);
    setEditor((current) => ({ ...next, idempotencyKey: current.idempotencyKey, name: preset.title, creative: { ...next.creative, image: current.creative.image, tabletImage: current.creative.tabletImage, mobileImage: current.creative.mobileImage } }));
  };

  const issues = useMemo(() => editor ? clientReadiness(editor) : { errors: [], warnings: [] }, [editor]);
  const nextStep = () => {
    const message = stepError(step, editor);
    if (message) return notify(message, 'error', 'Complete this step');
    setStep((value) => Math.min(STEPS.length - 1, value + 1));
  };
  const save = async (publish = false) => {
    if (saving) return;
    if (publish && issues.errors.length) { setStep(5); return notify(issues.errors[0], 'error', 'Campaign is not ready'); }
    setSaving(true);
    try {
      const body = payload(editor, publish);
      const saved = editor._id ? await api.put(`${base}/campaigns/${editor._id}`, body) : await api.post(`${base}/campaigns`, body);
      try { localStorage.removeItem(storageKey); } catch { /* ignore */ }
      notify(publish ? 'Campaign is synchronized and ready for its schedule.' : editor._id ? 'Campaign changes saved.' : 'Campaign draft saved.', 'success', 'Campaigns');
      setEditor(null); setDraftRestored(false); setPage(1); await load({ quiet: true });
      return saved;
    } catch (requestError) {
      notify(requestError.message, 'error', 'Campaigns');
      if (publish) await load({ quiet: true });
      return null;
    } finally { setSaving(false); }
  };
  const runAction = async (campaign, action) => {
    if (actionId) return;
    setActionId(campaign._id);
    try {
      if (action === 'DUPLICATE') await api.post(`${base}/campaigns/${campaign._id}/duplicate`, {});
      else if (action === 'REPAIR') await api.post(`${base}/campaigns/${campaign._id}/repair`, {});
      else await api.patch(`${base}/campaigns/${campaign._id}/status`, { action });
      notify(actionMessage(action), 'success', 'Campaigns'); setConfirm(null); await load({ quiet: true });
    } catch (requestError) { notify(requestError.message, 'error', 'Campaigns'); if (confirm) throw requestError; }
    finally { setActionId(''); }
  };
  const openInsights = async (campaign) => {
    setInsights(campaign); setInsightsLoading(true);
    try { setInsights(await api.get(`${base}/campaigns/${campaign._id}?range=${range}`, { silent: true })); }
    catch (requestError) { notify(requestError.message, 'error', 'Campaign insights'); }
    finally { setInsightsLoading(false); }
  };
  const toggleCompare = (campaign) => setCompareCampaigns((current) => {
    if (current.some((item) => item._id === campaign._id)) return current.filter((item) => item._id !== campaign._id);
    if (current.length >= 3) { notify('Compare up to three campaigns at a time.', 'error', 'Campaign comparison'); return current; }
    return [...current, campaign];
  });

  if (loading && !data) return <PageState loading loadingLabel="Loading campaigns and accurate performance..." />;
  if (error && !data) return <PageState error={error} onRetry={() => load()} />;

  return <section className="campaign-workspace mx-auto max-w-[1480px] space-y-5 pb-24 text-slate-900">
    {!editor && <PageHeader title="Campaigns" note="Plan the audience, offer, creative and schedule in one reliable workflow." />}
    {!editor && <>
      <header className="campaign-hero overflow-hidden rounded-[28px] bg-gradient-to-br from-[#67152f] via-[#842343] to-[#a74564] p-5 text-white shadow-[0_18px_55px_rgba(91,22,46,.2)] sm:p-7">
        <div className="flex flex-wrap items-end justify-between gap-5"><div><p className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.18em] text-white/65"><WandSparkles size={14} /> Campaign command center</p><h1 className="mt-2 font-display text-3xl font-black sm:text-4xl">Turn an offer into a measurable storefront moment</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-white/70">Draft safely, publish coupon and banner together, then follow clicks, orders and paid revenue.</p></div><button type="button" onClick={() => openNew()} className="flex h-12 items-center gap-2 rounded-xl bg-white px-5 text-sm font-black text-wine shadow-lg"><Plus size={17} /> Create campaign</button></div>
      </header>
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
        <Metric icon={Eye} label="Impressions" value={number(stats.impressions)} note={`${number(stats.ctr)}% click rate`} />
        <Metric icon={BarChart3} label="Clicks" value={number(stats.clicks)} note={`${number(stats.conversionRate)}% order conversion`} />
        <Metric icon={CheckCircle2} label="Orders" value={number(stats.orders)} note={`${number(stats.paidOrders)} paid or delivered`} />
        <Metric icon={CircleDollarSign} label="Paid revenue" value={`Rs. ${money(stats.revenue)}`} note={`Rs. ${money(stats.orderValue)} order value`} />
        <Metric icon={BadgePercent} label="Offer cost" value={`Rs. ${money(stats.discountCost)}`} note={`${number(stats.total)} current campaigns`} />
      </div>
      <article className="rounded-[24px] border border-[#eaded6] bg-white shadow-sm">
        <div className="flex flex-col gap-3 border-b border-[#eee5df] p-4 lg:flex-row lg:items-center lg:justify-between"><div className="flex gap-2 overflow-x-auto pb-1">{FILTERS.map((item) => <button key={item} type="button" onClick={() => { setFilter(item); setPage(1); }} className={`shrink-0 rounded-full px-3 py-2 text-[11px] font-black ${filter === item ? 'bg-wine text-white' : 'bg-[#f8f3ef] text-slate-600'}`}>{titleCase(item)}{stats.byStatus?.[titleCase(item)] != null ? ` ${stats.byStatus[titleCase(item)]}` : ''}</button>)}</div><div className="flex gap-2"><select aria-label="Performance range" value={range} onChange={(event) => setRange(event.target.value)} className="h-10 rounded-xl border border-[#e2d7d0] bg-white px-3 text-xs font-bold"><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option></select><input aria-label="Search campaigns" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Search name or code" className="h-10 min-w-0 rounded-xl border border-[#e2d7d0] px-3 text-sm outline-none focus:border-[#9d4865]" /><button type="button" aria-label="Refresh campaigns" onClick={() => load({ quiet: true })} disabled={refreshing} className="grid h-10 w-10 shrink-0 place-items-center rounded-xl border"><RefreshCw size={15} className={refreshing ? 'animate-spin' : ''} /></button></div></div>
        {error && <div className="m-4 flex items-center justify-between gap-3 rounded-xl bg-rose-50 p-3 text-sm font-bold text-rose-800"><span>{error}</span><button type="button" onClick={() => load()} className="underline">Retry</button></div>}
        {!data?.items?.length ? <div className="p-10 text-center"><Megaphone className="mx-auto text-[#c5a9b3]" /><h2 className="mt-3 font-display text-2xl font-black">No campaigns in this view</h2><p className="mt-1 text-sm text-slate-500">Create a guided campaign or choose another status.</p><button type="button" onClick={() => openNew()} className="admin-btn mx-auto mt-5"><Plus size={16} /> Create campaign</button></div> : <div className="grid gap-4 p-4 xl:grid-cols-2">{data.items.map((campaign) => <CampaignCard key={campaign._id} campaign={campaign} busy={actionId === campaign._id} comparing={compareCampaigns.some((item) => item._id === campaign._id)} onCompare={() => toggleCompare(campaign)} onEdit={() => edit(campaign)} onExtend={() => extend(campaign)} onInsights={() => openInsights(campaign)} onAction={(action) => action === 'ARCHIVE' ? setConfirm({ campaign, action }) : runAction(campaign, action)} />)}</div>}
        {data?.totalPages > 1 && <footer className="flex items-center justify-between border-t p-4 text-xs font-bold text-slate-500"><span>Page {data.page} of {data.totalPages} | {number(data.total)} campaigns</span><div className="flex gap-2"><button type="button" disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="admin-btn-ghost disabled:opacity-40">Previous</button><button type="button" disabled={page >= data.totalPages} onClick={() => setPage((value) => value + 1)} className="admin-btn-ghost disabled:opacity-40">Next</button></div></footer>}
      </article>
      {compareCampaigns.length > 0 && <div className="sticky bottom-4 z-30 flex flex-col gap-3 rounded-2xl border border-[#d8bcc6] bg-white/95 p-4 shadow-[0_16px_45px_rgba(70,24,40,.2)] backdrop-blur sm:flex-row sm:items-center sm:justify-between"><div><strong className="text-sm text-wine">{compareCampaigns.length} campaign{compareCampaigns.length === 1 ? '' : 's'} selected</strong><p className="mt-0.5 text-[11px] text-slate-500">Choose two or three campaigns to compare their current {range}-day results.</p></div><div className="flex gap-2"><button type="button" onClick={() => setCompareCampaigns([])} className="admin-btn-ghost">Clear</button><button type="button" disabled={compareCampaigns.length < 2} onClick={() => setCompareOpen(true)} className="admin-btn disabled:opacity-40"><BarChart3 size={15} /> Compare results</button></div></div>}
    </>}
    {editor && <CampaignEditor form={editor} step={step} setStep={setStep} issues={issues} options={options} preview={preview} setPreview={setPreview} update={update} updateOffer={updateOffer} updateCreative={updateCreative} choosePreset={choosePreset} draftRestored={draftRestored} onDiscard={discardLocalDraft} base={base} saving={saving} onClose={closeEditor} onBack={() => setStep((value) => Math.max(0, value - 1))} onNext={nextStep} onSave={() => save(false)} onPublish={() => save(true)} />}
    <ConfirmModal open={Boolean(confirm)} title="Archive campaign?" message={`${confirm?.campaign?.name || 'This campaign'} will be hidden with its linked coupon and banner. Performance history will remain available and the campaign can be restored.`} confirmLabel="Archive campaign" onClose={() => !actionId && setConfirm(null)} onConfirm={() => runAction(confirm.campaign, confirm.action)} />
    {insights && <CampaignInsights campaign={insights} loading={insightsLoading} range={range} onClose={() => !insightsLoading && setInsights(null)} />}
    {compareOpen && <CampaignComparison campaigns={compareCampaigns} range={range} onClose={() => setCompareOpen(false)} />}
  </section>;
}

function CampaignCard({ campaign, busy, comparing, onCompare, onEdit, onExtend, onInsights, onAction }) {
  const performance = campaign.performance || {}; const tone = statusTone(campaign.lifecycle); const canEdit = campaign.lifecycle !== 'Archived';
  return <article className="group overflow-hidden rounded-[22px] border border-[#eaded6] bg-ivory transition hover:-translate-y-0.5 hover:border-[#cb8da2] hover:shadow-lg"><div className="grid grid-cols-[92px_1fr] gap-4 p-4 sm:grid-cols-[126px_1fr]"><div className="h-28 overflow-hidden rounded-2xl bg-[#f3e9e4] sm:h-32">{campaign.creative?.image ? <img src={campaign.creative.image} alt={campaign.creative.altText || ''} className="h-full w-full object-cover" /> : <span className="grid h-full place-items-center text-[#b48797]"><Megaphone /></span>}</div><div className="min-w-0"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className={`rounded-full px-2.5 py-1 text-[9px] font-black uppercase tracking-wider ${tone}`}>{campaign.lifecycle}</span><span className="text-[10px] font-black uppercase tracking-wider text-slate-400">{titleCase(campaign.preset)}</span>{campaign.health && <span className={`rounded-full px-2.5 py-1 text-[9px] font-black uppercase tracking-wider ${campaign.health.synchronized ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-800'}`}>{campaign.health.synchronized ? 'Synced' : 'Needs repair'}</span>}</div><h2 className="mt-2 truncate font-display text-xl font-black" title={campaign.name}>{campaign.name}</h2><p className="mt-1 text-xs font-bold text-[#8a3d59]">{campaign.offer?.code || 'Code pending'} | {offerLabel(campaign.offer)}</p></div><MoreHorizontal className="shrink-0 text-slate-300" /></div><p className="mt-3 text-[11px] leading-5 text-slate-500">{scheduleLabel(campaign)}</p>{campaign.lastError && <p className="mt-2 line-clamp-2 rounded-lg bg-rose-50 px-2 py-1.5 text-[10px] font-bold text-rose-700">{campaign.lastError}</p>}</div></div><div className="grid grid-cols-4 border-y border-[#eee5df] bg-white/80"><Mini label="Views" value={number(performance.impressions)} /><Mini label="Clicks" value={number(performance.clicks)} /><Mini label="Orders" value={number(performance.orders)} /><Mini label="Revenue" value={`Rs. ${compactMoney(performance.revenue)}`} /></div><div className="flex flex-wrap gap-2 p-3"><button type="button" disabled={busy} onClick={onInsights} className="card-action"><BarChart3 size={13} /> Insights</button><button type="button" disabled={busy} aria-pressed={comparing} onClick={onCompare} className={`card-action ${comparing ? 'card-action--primary' : ''}`}><Check size={13} /> {comparing ? 'Compared' : 'Compare'}</button>{canEdit && <button type="button" disabled={busy} onClick={onEdit} className="card-action"><Pencil size={13} /> Edit</button>}{campaign.lifecycle === 'Ended' && <button type="button" disabled={busy} onClick={onExtend} className="card-action card-action--primary"><Clock3 size={13} /> Extend</button>}{['Draft', 'Paused'].includes(campaign.lifecycle) && <button type="button" disabled={busy} onClick={() => onAction('PUBLISH')} className="card-action card-action--primary"><Rocket size={13} /> Publish</button>}{['Live', 'Scheduled', 'Ended'].includes(campaign.lifecycle) && <button type="button" disabled={busy} onClick={() => onAction('PAUSE')} className="card-action"><Pause size={13} /> Pause</button>}{campaign.lifecycle !== 'Archived' && campaign.health && !campaign.health.synchronized && <button type="button" disabled={busy} onClick={() => onAction('REPAIR')} className="card-action card-action--primary"><RotateCcw size={13} /> Repair</button>}<button type="button" disabled={busy} onClick={() => onAction('DUPLICATE')} className="card-action"><Copy size={13} /> Copy</button>{campaign.lifecycle === 'Archived' ? <button type="button" disabled={busy} onClick={() => onAction('RESTORE')} className="card-action"><RotateCcw size={13} /> Restore</button> : <button type="button" disabled={busy} onClick={() => onAction('ARCHIVE')} className="card-action"><Archive size={13} /> Archive</button>}</div></article>;
}

function CampaignInsights({ campaign, loading, range, onClose }) {
  const performance = campaign.performance || {};
  const funnel = [
    ['Impressions', performance.impressions], ['Clicks', performance.clicks], ['Product views', performance.productViews],
    ['Bag additions', performance.addToCarts], ['Checkouts', performance.checkouts], ['Orders', performance.orders], ['Paid orders', performance.paidOrders],
  ];
  const maximum = Math.max(1, ...funnel.map(([, value]) => Number(value || 0)));
  return <div className="fixed inset-0 z-[90] flex items-end justify-center bg-black/45 p-0 backdrop-blur-sm sm:items-center sm:p-5" role="dialog" aria-modal="true" aria-label={`${campaign.name} campaign insights`}><article className="max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-t-[28px] bg-white shadow-2xl sm:rounded-[28px]"><header className="sticky top-0 z-10 flex items-start justify-between gap-4 border-b bg-white/95 p-5 backdrop-blur sm:p-6"><div><p className="text-[10px] font-black uppercase tracking-[0.18em] text-wine">{range}-day performance</p><h2 className="mt-1 font-display text-2xl font-black">{campaign.name}</h2><p className="mt-1 text-xs text-slate-500">{titleCase(campaign.offer?.customerSegment || 'ALL')} audience | {campaign.offer?.code || 'No code'}</p></div><button type="button" disabled={loading} onClick={onClose} aria-label="Close campaign insights" className="grid h-10 w-10 place-items-center rounded-full border text-slate-500"><XCircle size={19} /></button></header>{loading ? <div className="grid min-h-72 place-items-center"><RefreshCw className="animate-spin text-wine" /></div> : <div className="space-y-6 p-5 sm:p-6"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric icon={CircleDollarSign} label="Paid revenue" value={`Rs. ${money(performance.revenue)}`} note={`AOV Rs. ${money(performance.averageOrderValue)}`} /><Metric icon={BadgePercent} label="Offer cost" value={`Rs. ${money(performance.discountCost)}`} note={`${number(performance.uniqueCustomers)} customers`} /><Metric icon={CheckCircle2} label="Orders" value={number(performance.orders)} note={`${number(performance.cancelled)} cancelled`} /><Metric icon={RotateCcw} label="Returns" value={number(performance.returned)} note={`${number(performance.conversionRate)}% conversion`} /></div><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><section className="rounded-2xl border border-[#eaded6] p-4"><h3 className="font-display text-xl font-black">Customer funnel</h3><div className="mt-4 space-y-3">{funnel.map(([label, value]) => <div key={label}><div className="mb-1 flex justify-between text-xs font-bold"><span>{label}</span><span>{number(value)}</span></div><div className="h-2 overflow-hidden rounded-full bg-[#f3ebe7]"><div className="h-full rounded-full bg-gradient-to-r from-wine to-[#d65a82]" style={{ width: `${Math.max(Number(value || 0) ? 3 : 0, (Number(value || 0) / maximum) * 100)}%` }} /></div></div>)}</div></section><section className="rounded-2xl border border-[#eaded6] p-4"><h3 className="font-display text-xl font-black">Campaign health</h3><div className={`mt-4 rounded-xl p-3 text-sm font-bold ${campaign.health?.synchronized ? 'bg-emerald-50 text-emerald-800' : 'bg-amber-50 text-amber-900'}`}>{campaign.health?.synchronized ? 'Coupon, banner and campaign settings are synchronized.' : 'This campaign needs repair before it can be trusted.'}</div><div className="mt-3 space-y-2">{(campaign.health?.issues || []).map((issue) => <Issue key={issue} error text={issue} />)}<ReviewRow label="Linked coupon" value={campaign.linkedCoupon?.code || 'Not created'} /><ReviewRow label="Banner creatives" value={String(campaign.linkedBanners?.length || 0)} /><ReviewRow label="Schedule" value={scheduleLabel(campaign)} />{campaign.schedule?.clear === false && <div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900"><strong className="block font-black">Schedule overlap</strong><span className="mt-1 block">This placement also contains {(campaign.schedule.conflicts || []).map((item) => item.name).join(', ') || 'another live campaign'}. Review the dates or banner position before publishing.</span></div>}</div></section></div>{performance.daily?.length > 0 && <section className="rounded-2xl border border-[#eaded6] p-4"><h3 className="font-display text-xl font-black">Daily results</h3><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{performance.daily.map((day) => <div key={day.date} className="rounded-xl bg-[#fbf7f4] p-3"><strong className="text-xs">{day.date}</strong><p className="mt-1 text-[11px] text-slate-500">{number(day.impressions)} views | {number(day.clicks)} clicks | {number(day.orders)} orders</p><p className="mt-1 text-sm font-black text-wine">Rs. {money(day.revenue)}</p></div>)}</div></section>}</div>}</article></div>;
}

function CampaignComparison({ campaigns, range, onClose }) {
  const metrics = [
    ['Impressions', (item) => Number(item.performance?.impressions || 0), number],
    ['Clicks', (item) => Number(item.performance?.clicks || 0), number],
    ['Click rate', (item) => Number(item.performance?.ctr || 0), (value) => `${number(value)}%`],
    ['Orders', (item) => Number(item.performance?.orders || 0), number],
    ['Conversion', (item) => Number(item.performance?.conversionRate || 0), (value) => `${number(value)}%`],
    ['Paid revenue', (item) => Number(item.performance?.revenue || 0), (value) => `Rs. ${money(value)}`],
    ['Average order', (item) => Number(item.performance?.averageOrderValue || 0), (value) => `Rs. ${money(value)}`],
    ['Offer cost', (item) => Number(item.performance?.discountCost || 0), (value) => `Rs. ${money(value)}`],
  ];
  return <div className="fixed inset-0 z-[90] flex items-end justify-center bg-black/45 p-0 backdrop-blur-sm sm:items-center sm:p-5" role="dialog" aria-modal="true" aria-label="Campaign comparison"><article className="max-h-[92vh] w-full max-w-5xl overflow-y-auto rounded-t-[28px] bg-white shadow-2xl sm:rounded-[28px]"><header className="sticky top-0 z-10 flex items-start justify-between gap-4 border-b bg-white/95 p-5 backdrop-blur sm:p-6"><div><p className="text-[10px] font-black uppercase tracking-[0.18em] text-wine">{range}-day comparison</p><h2 className="mt-1 font-display text-2xl font-black">Compare campaign results</h2><p className="mt-1 text-xs text-slate-500">Every value uses the same server-calculated reporting window.</p></div><button type="button" onClick={onClose} aria-label="Close campaign comparison" className="grid h-10 w-10 place-items-center rounded-full border text-slate-500"><XCircle size={19} /></button></header><div className="overflow-x-auto p-5 sm:p-6"><table className="w-full min-w-[680px] border-separate border-spacing-0 overflow-hidden rounded-2xl border border-[#eaded6] text-left"><thead><tr className="bg-[#fbf6f2]"><th className="w-40 border-b p-4 text-[10px] font-black uppercase tracking-wider text-slate-500">Metric</th>{campaigns.map((campaign) => <th key={campaign._id} className="min-w-[170px] border-b border-l p-4"><span className={`rounded-full px-2 py-1 text-[9px] font-black uppercase ${statusTone(campaign.lifecycle)}`}>{campaign.lifecycle}</span><strong className="mt-2 block truncate text-sm" title={campaign.name}>{campaign.name}</strong><span className="mt-1 block text-[10px] text-slate-500">{campaign.offer?.code || 'No code'}</span></th>)}</tr></thead><tbody>{metrics.map(([label, read, format]) => { const values = campaigns.map(read); const best = Math.max(...values); return <tr key={label}><th className="border-b p-4 text-xs font-bold text-slate-600">{label}</th>{values.map((value, index) => <td key={campaigns[index]._id} className={`border-b border-l p-4 text-sm font-black ${value === best && best > 0 ? 'bg-emerald-50 text-emerald-800' : 'text-slate-800'}`}>{format(value)}</td>)}</tr>; })}</tbody></table><p className="mt-4 text-[11px] leading-5 text-slate-500">Highlighted values are the highest in each row. Offer cost should be reviewed together with paid revenue and conversion.</p></div></article></div>;
}

function CampaignEditor({ form, step, setStep, issues, options, preview, setPreview, update, updateOffer, updateCreative, choosePreset, draftRestored, onDiscard, base, saving, onClose, onBack, onNext, onSave, onPublish }) {
  const published = form.state === 'PUBLISHED';
  return <article className="overflow-hidden rounded-[28px] border border-[#e2d4cd] bg-white shadow-[0_20px_60px_rgba(72,28,42,.12)]"><div className="p-5"><WorkflowSmartFill key={form._id || form.idempotencyKey} workflow="campaign" form={form} apiBase={`${base}/smart-fill`} disabled={saving} onChange={(next, rows) => { for (const row of rows) { if (row.path.startsWith("creative.")) updateCreative(row.path.slice(9), next.creative[row.path.slice(9)]); else update(row.path, next[row.path]); } }} /></div><header className="border-b bg-gradient-to-r from-[#fff8f3] to-blush p-5 sm:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><button type="button" onClick={onClose} className="mb-3 flex items-center gap-2 text-xs font-black text-wine"><ArrowLeft size={14} /> Back to campaigns</button><p className="text-[10px] font-black uppercase tracking-[0.18em] text-wine">{form._id ? 'Edit campaign' : 'New campaign'}</p><h1 className="mt-1 font-display text-3xl font-black">{form.name || 'Untitled campaign'}</h1><p className="mt-1 text-sm text-slate-500">Coupon, banner and attribution share one campaign identity.</p></div><span className="rounded-full border border-[#dfcbd2] bg-white px-3 py-2 text-[10px] font-black uppercase tracking-wider">Step {step + 1} of {STEPS.length}</span></div>{draftRestored && <div className="mt-4 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-blue-200 bg-blue-50 p-3 text-xs font-bold text-blue-800"><span className="flex items-start gap-2"><RotateCcw size={15} className="shrink-0" /> Your unsaved campaign draft was restored from this browser.</span><button type="button" onClick={onDiscard} className="rounded-lg bg-white px-3 py-1.5 text-[10px] font-black text-blue-800">Discard local draft</button></div>}<nav className="mt-5 flex gap-2 overflow-x-auto pb-1" aria-label="Campaign setup steps">{STEPS.map((item, index) => <button key={item} type="button" onClick={() => index <= step && setStep(index)} className={`flex shrink-0 items-center gap-2 rounded-full px-3 py-2 text-[10px] font-black uppercase tracking-wider ${index === step ? 'bg-wine text-white' : index < step ? 'bg-emerald-50 text-emerald-700' : 'bg-white text-slate-400'}`}>{index < step ? <Check size={12} /> : index + 1} {item}</button>)}</nav></header><div className="min-h-[480px] p-4 sm:p-7">{step === 0 && <GoalStep form={form} update={update} choosePreset={choosePreset} base={base} />}{step === 1 && <AudienceStep form={form} options={options} updateOffer={updateOffer} updateCreative={updateCreative} />}{step === 2 && <OfferStep form={form} updateOffer={updateOffer} />}{step === 3 && <CreativeStep form={form} updateCreative={updateCreative} />}{step === 4 && <ScheduleStep form={form} update={update} updateOffer={updateOffer} />}{step === 5 && <ReviewStep form={form} issues={issues} preview={preview} setPreview={setPreview} />}</div><footer className="sticky bottom-0 z-20 flex flex-col-reverse gap-2 border-t border-[#eaded6] bg-white/95 p-4 backdrop-blur sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-2"><button type="button" onClick={step ? onBack : onClose} className="admin-btn-ghost"><ArrowLeft size={15} /> {step ? 'Back' : 'Cancel'}</button><button type="button" disabled={saving} onClick={onSave} className="admin-btn-ghost">{saving ? 'Saving...' : published ? 'Save changes' : 'Save draft'}</button></div>{step < STEPS.length - 1 ? <button type="button" onClick={onNext} className="admin-btn">Continue <ArrowRight size={15} /></button> : <button type="button" disabled={saving || issues.errors.length > 0} onClick={onPublish} className="admin-btn disabled:opacity-45"><Rocket size={15} /> {saving ? 'Publishing...' : published ? 'Save and synchronize' : 'Publish campaign'}</button>}</footer></article>;
}

function GoalStep({ form, update, choosePreset, base }) { return <div className="space-y-6"><SectionTitle eyebrow="Campaign goal" title="What should this campaign achieve?" note="The preset fills sensible defaults. Every value remains editable before publishing." /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{PRESETS.map((preset) => <button key={preset.id} type="button" onClick={() => choosePreset(preset)} className={`rounded-2xl border p-4 text-left transition ${form.preset === preset.id ? 'border-[#8d3554] bg-[#fff4f7] shadow-sm' : 'border-[#e8ddd6] hover:border-[#c994a6]'}`}><preset.icon className="text-[#8d3554]" size={20} /><strong className="mt-4 block text-sm">{preset.title}</strong><span className="mt-1 block text-xs leading-5 text-slate-500">{preset.note}</span></button>)}</div><div className="grid gap-4 lg:grid-cols-2"><Field label="Campaign name" note="Used in reports and the campaign list"><input value={form.name} maxLength={120} onChange={(event) => update('name', event.target.value)} placeholder="Diwali celebration" /></Field><InfoCard icon={Gift} title="Recover abandoned bags" text="Recovery uses customer-specific reminders and consent rules, so it lives in Business Center." link={`${base}/business#recovery`} linkLabel="Open checkout recovery" /></div></div>; }

function AudienceStep({ form, options, updateOffer, updateCreative }) { const offer = form.offer; const changeSegment = (value) => { updateOffer('customerSegment', value); if (value === 'REPEAT' && !Number(offer.minimumPriorOrders)) updateOffer('minimumPriorOrders', 1); if (value === 'VIP') { if (!Number(offer.minimumPriorOrders)) updateOffer('minimumPriorOrders', 5); if (!Number(offer.minimumLifetimeSpend)) updateOffer('minimumLifetimeSpend', 25000); } if (value === 'INACTIVE' && !Number(offer.inactiveDays)) updateOffer('inactiveDays', 90); }; return <div className="space-y-6"><SectionTitle eyebrow="Audience and scope" title="Decide who receives the offer" note="Keep it broad or narrow it by customer, product, category, PIN code, payment method and channel." /><div className="grid gap-4 lg:grid-cols-3"><Field label="Customer audience"><select value={offer.customerSegment} onChange={(event) => changeSegment(event.target.value)}><option value="ALL">All customers</option><option value="NEW">New customers</option><option value="REPEAT">Repeat customers</option><option value="VIP">VIP customers</option><option value="INACTIVE">Inactive customers</option><option value="SELECTED">Selected customers</option></select></Field><Field label="Scope matching" note="When product and category are both selected"><select value={offer.scopeMatchMode} onChange={(event) => updateOffer('scopeMatchMode', event.target.value)}><option value="ANY">Match either</option><option value="ALL">Must match all</option></select></Field><Field label="Minimum calculated on"><select value={offer.minimumRequirementBasis} onChange={(event) => updateOffer('minimumRequirementBasis', event.target.value)}><option value="CART">Entire cart</option><option value="ELIGIBLE_ITEMS">Eligible items only</option></select></Field></div><div className="grid gap-4 xl:grid-cols-3"><OptionPicker title="Products" items={options.PRODUCT} selected={offer.applicableProducts} onChange={(value) => { updateOffer('applicableProducts', value); if (form.creative.destinationType === 'PRODUCT') updateCreative('destinationValue', value[0] || ''); }} /><OptionPicker title="Categories" items={options.CATEGORY} selected={offer.applicableCategories} onChange={(value) => { updateOffer('applicableCategories', value); if (form.preset === 'CATEGORY' || form.creative.destinationType === 'CATEGORY') updateCreative('destinationValue', value[0] || ''); }} /><OptionPicker title="Customers" items={options.CUSTOMER} selected={offer.applicableCustomers} onChange={(value) => { updateOffer('applicableCustomers', value); if (value.length) updateOffer('customerSegment', 'SELECTED'); }} /></div><div className="grid gap-4 lg:grid-cols-2"><Field label="Serviceable PIN codes" note="Leave blank for all PIN codes; separate with commas"><textarea value={(offer.applicablePincodes || []).join(', ')} onChange={(event) => updateOffer('applicablePincodes', event.target.value.split(/[\s,]+/).filter(Boolean))} placeholder="110001, 176001" /></Field><ChoiceGroup label="Payment methods" choices={['COD', 'UPI', 'CARD', 'NETBANKING', 'WALLET', 'RAZORPAY']} selected={offer.applicablePaymentMethods} onChange={(value) => updateOffer('applicablePaymentMethods', value)} /><ChoiceGroup label="Sales channels" choices={['STOREFRONT', 'ADMIN', 'SOCIAL']} selected={offer.salesChannels} onChange={(value) => updateOffer('salesChannels', value)} /></div></div>; }

function OfferStep({ form, updateOffer }) { const offer = form.offer; return <div className="space-y-6"><SectionTitle eyebrow="Offer rules" title="Set a benefit with clear commercial limits" note="These rules are enforced by checkout on the backend." /><div className="grid gap-4 lg:grid-cols-3"><Field label="Coupon code"><input value={offer.code} maxLength={32} onChange={(event) => updateOffer('code', codeFrom(event.target.value))} /></Field><Field label="Activation"><select value={offer.activationMode} onChange={(event) => updateOffer('activationMode', event.target.value)}><option value="CODE">Customer enters code</option><option value="AUTOMATIC">Apply automatically</option></select></Field><Field label="Benefit"><select value={offer.benefitType} onChange={(event) => updateOffer('benefitType', event.target.value)}><option value="DISCOUNT">Discount</option><option value="FREE_SHIPPING">Free shipping</option><option value="BUY_X_GET_Y">Buy X, get Y</option></select></Field></div>{offer.benefitType === 'DISCOUNT' && <div className="grid gap-4 sm:grid-cols-2"><Field label="Discount type"><select value={offer.type} onChange={(event) => updateOffer('type', event.target.value)}><option>Percentage</option><option>Flat</option></select></Field><Field label={offer.type === 'Percentage' ? 'Discount percent' : 'Discount amount'}><input type="number" min="0" max={offer.type === 'Percentage' ? 100 : undefined} value={offer.discountValue} onChange={(event) => updateOffer('discountValue', event.target.value)} /></Field></div>}{offer.benefitType === 'BUY_X_GET_Y' && <div className="grid gap-4 sm:grid-cols-2"><Field label="Customer buys"><input type="number" min="1" value={offer.buyQuantity} onChange={(event) => updateOffer('buyQuantity', event.target.value)} /></Field><Field label="Customer gets free"><input type="number" min="1" value={offer.getQuantity} onChange={(event) => updateOffer('getQuantity', event.target.value)} /></Field></div>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Field label="Minimum order"><MoneyInput value={offer.minOrderAmount} onChange={(value) => updateOffer('minOrderAmount', value)} /></Field><Field label="Minimum items"><input type="number" min="0" value={offer.minItemQuantity} onChange={(event) => updateOffer('minItemQuantity', event.target.value)} /></Field><Field label={offer.benefitType === 'FREE_SHIPPING' ? 'Maximum shipping benefit' : 'Maximum discount'}><MoneyInput value={offer.maxDiscountAmount} onChange={(value) => updateOffer('maxDiscountAmount', value)} /></Field><Field label="Per-customer uses"><input type="number" min="0" value={offer.customerLimit} onChange={(event) => updateOffer('customerLimit', event.target.value)} /></Field></div>{['REPEAT', 'VIP'].includes(offer.customerSegment) && <div className="grid gap-4 sm:grid-cols-2"><Field label="Minimum previous orders" note={offer.customerSegment === 'VIP' ? 'VIP qualifies by this order count or lifetime spend' : 'Required before the offer can be used'}><input type="number" min="1" value={offer.minimumPriorOrders || ''} onChange={(event) => updateOffer('minimumPriorOrders', event.target.value)} /></Field>{offer.customerSegment === 'VIP' && <Field label="Minimum lifetime spend" note="VIP qualifies when either threshold is met"><MoneyInput value={offer.minimumLifetimeSpend} onChange={(value) => updateOffer('minimumLifetimeSpend', value)} /></Field>}</div>}{offer.customerSegment === 'INACTIVE' && <Field label="Days since last order" note="Customer must have an earlier order and no newer qualifying order"><input type="number" min="1" max="3650" value={offer.inactiveDays || 90} onChange={(event) => updateOffer('inactiveDays', event.target.value)} /></Field>}<div className="grid gap-3 sm:grid-cols-2"><Toggle checked={offer.firstOrderOnly} onChange={(value) => updateOffer('firstOrderOnly', value)} title="First order only" note="Checkout verifies the customer's order history." /><Toggle checked={offer.isPublic} onChange={(value) => updateOffer('isPublic', value)} title="Show in available coupons" note="Keep VIP and selected-customer codes private." /><Toggle checked={offer.stackingMode === 'EXCLUSIVE'} onChange={(value) => updateOffer('stackingMode', value ? 'EXCLUSIVE' : 'ALLOW_PRODUCT_OFFERS')} title="Exclude already discounted items" note="Useful when the campaign should apply to full-price lines only." /><Toggle checked={offer.restoreOnFullRefund} onChange={(value) => updateOffer('restoreOnFullRefund', value)} title="Restore use after full refund" note="Returns the coupon use only after the complete order is refunded." /></div></div>; }

function CreativeStep({ form, updateCreative }) { const creative = form.creative; return <div className="space-y-6"><SectionTitle eyebrow="Storefront creative" title="Build a responsive campaign banner" note="Desktop and mobile assets keep the campaign clear on every screen." /><div className="grid gap-4 lg:grid-cols-3"><ImageUploader label="Desktop image" helpText="Recommended 1600 x 600, JPG/PNG/WEBP" uploadContext="banners" value={creative.image ? [{ url: creative.image }] : []} onChange={(images) => updateCreative('image', images[0]?.url || '')} /><ImageUploader label="Tablet image" helpText="Optional, recommended 1200 x 700" uploadContext="banners" value={creative.tabletImage ? [{ url: creative.tabletImage }] : []} onChange={(images) => updateCreative('tabletImage', images[0]?.url || '')} /><ImageUploader label="Mobile image" helpText="Recommended 900 x 1100" uploadContext="banners" value={creative.mobileImage ? [{ url: creative.mobileImage }] : []} onChange={(images) => updateCreative('mobileImage', images[0]?.url || '')} /></div><div className="grid gap-4 lg:grid-cols-2"><Field label="Banner headline"><input value={creative.title} maxLength={120} onChange={(event) => updateCreative('title', event.target.value)} /></Field><Field label="Button label"><input value={creative.buttonText} maxLength={60} onChange={(event) => updateCreative('buttonText', event.target.value)} /></Field><Field label="Supporting text"><textarea value={creative.subtitle} maxLength={300} onChange={(event) => updateCreative('subtitle', event.target.value)} /></Field><Field label="Image description" note="Describe the image for screen readers"><textarea value={creative.altText} maxLength={180} onChange={(event) => updateCreative('altText', event.target.value)} /></Field></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Field label="Placement"><select value={creative.position} onChange={(event) => updateCreative('position', event.target.value)}>{['Home - Top', 'Home - Middle', 'Home - Bottom', 'Cart - Bottom', 'Category - Featured', 'Offer Strip'].map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Banner style"><select value={creative.type} onChange={(event) => updateCreative('type', event.target.value)}>{['Hero', 'Offer', 'Category', 'Sale'].map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Image focus"><select value={creative.focalPoint} onChange={(event) => updateCreative('focalPoint', event.target.value)}>{['center', 'top', 'bottom', 'left', 'right'].map((item) => <option key={item}>{titleCase(item)}</option>)}</select></Field><Field label="Display order"><input type="number" min="0" value={creative.displayOrder} onChange={(event) => updateCreative('displayOrder', event.target.value)} /></Field></div><div className="grid gap-4 lg:grid-cols-2"><Field label="Button opens"><select value={creative.destinationType} onChange={(event) => updateCreative('destinationType', event.target.value)}><option value="CUSTOM">Custom page</option><option value="PRODUCT">Product</option><option value="CATEGORY">Category</option><option value="COLLECTION">Collection</option><option value="COUPON">Shopping bag with coupon</option></select></Field>{creative.destinationType === 'CUSTOM' ? <Field label="Internal path or secure URL"><input value={creative.link} onChange={(event) => updateCreative('link', event.target.value)} placeholder="/products" /></Field> : creative.destinationType === 'COUPON' ? <InfoCard icon={BadgePercent} title={`Coupon ${form.offer.code || 'pending'}`} text="The campaign coupon is added to the shopping bag link automatically." /> : <Field label={`${titleCase(creative.destinationType)} identifier`} note="Select the matching target on the Audience step"><input value={creative.destinationValue} onChange={(event) => updateCreative('destinationValue', event.target.value)} placeholder="Paste the selected ID or collection name" /></Field>}</div></div>; }

function ScheduleStep({ form, update, updateOffer }) { return <div className="space-y-6"><SectionTitle eyebrow="Schedule and safeguards" title="Control timing, usage and budget" note="The server applies these limits even if somebody changes browser code." /><div className="grid gap-4 lg:grid-cols-3"><Field label="Starts at" note="Leave blank to start when published"><input type="datetime-local" value={form.startsAt} onChange={(event) => update('startsAt', event.target.value)} /></Field><Field label="Ends at" note={form.preset === 'FLASH' ? 'Required for flash campaigns' : 'Recommended'}><input type="datetime-local" value={form.endsAt} onChange={(event) => update('endsAt', event.target.value)} /></Field><Field label="Reporting timezone"><select value={form.timezone} onChange={(event) => update('timezone', event.target.value)}><option>Asia/Kolkata</option><option>UTC</option></select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Total coupon uses" note="0 means unlimited"><input type="number" min="0" value={form.offer.usageLimit} onChange={(event) => updateOffer('usageLimit', event.target.value)} /></Field><Field label="Maximum campaign budget" note="0 means no budget cap"><MoneyInput value={form.offer.totalBudget} onChange={(value) => updateOffer('totalBudget', value)} /></Field></div><div className="rounded-2xl border border-blue-200 bg-blue-50 p-4 text-sm leading-6 text-blue-900"><strong>Schedule behavior</strong><p>A published campaign stays hidden until its start time and stops at its end time. Pausing disables both its coupon and banner immediately.</p></div></div>; }

function ReviewStep({ form, issues, preview, setPreview }) { return <div className="space-y-6"><SectionTitle eyebrow="Final review" title="Check the customer experience before publishing" note="Publishing validates and synchronizes the coupon and banner as one operation." /><div className="grid gap-5 xl:grid-cols-[.85fr_1.15fr]"><div className="space-y-4"><ReviewBlock title="Campaign"><ReviewRow label="Goal" value={titleCase(form.preset)} /><ReviewRow label="Audience" value={titleCase(form.offer.customerSegment)} /><ReviewRow label="Offer" value={`${form.offer.code || 'Missing code'} | ${offerLabel(form.offer)}`} /><ReviewRow label="Schedule" value={scheduleLabel(form)} /></ReviewBlock><ReviewBlock title="Publish readiness">{issues.errors.map((item) => <Issue key={item} error text={item} />)}{issues.warnings.map((item) => <Issue key={item} text={item} />)}{!issues.errors.length && <Issue success text="Required campaign details are complete." />}</ReviewBlock></div><div><div className="mb-3 flex justify-end gap-2"><button type="button" onClick={() => setPreview('desktop')} className={`preview-toggle ${preview === 'desktop' ? 'preview-toggle--active' : ''}`}><Monitor size={14} /> Desktop</button><button type="button" onClick={() => setPreview('mobile')} className={`preview-toggle ${preview === 'mobile' ? 'preview-toggle--active' : ''}`}><Smartphone size={14} /> Mobile</button></div><CampaignPreview form={form} mobile={preview === 'mobile'} /></div></div></div>; }

function CampaignPreview({ form, mobile }) { const creative = form.creative; const image = mobile ? creative.mobileImage || creative.image : creative.image; return <div className={`mx-auto overflow-hidden rounded-[22px] border border-[#decfc8] bg-[#f7eee9] shadow-xl transition-all ${mobile ? 'max-w-[360px]' : 'w-full'}`}><div className={`relative ${mobile ? 'aspect-[4/5]' : 'aspect-[16/6]'}`}>{image ? <img src={image} alt={creative.altText || ''} className="h-full w-full object-cover" style={{ objectPosition: creative.focalPoint }} /> : <div className="grid h-full place-items-center text-sm font-bold text-slate-400">Campaign image preview</div>}<div className="absolute inset-0 bg-gradient-to-r from-black/55 via-black/20 to-transparent" /><div className="absolute inset-x-0 bottom-0 p-5 text-white"><p className="text-[9px] font-black uppercase tracking-[0.2em]">{form.offer.code || 'Offer code'}</p><h3 className="mt-1 font-display text-2xl font-black">{creative.title || form.name}</h3>{creative.subtitle && <p className="mt-1 line-clamp-2 text-xs text-white/80">{creative.subtitle}</p>}<span className="mt-3 inline-flex rounded-lg bg-white px-3 py-2 text-[10px] font-black text-wine">{creative.buttonText || 'Shop now'}</span></div></div></div>; }

function OptionPicker({ title, items, selected = [], onChange }) { const selectedSet = new Set(selected.map(String)); return <fieldset className="rounded-2xl border border-[#e9ddd6] p-4"><legend className="px-1 text-xs font-black">{title}</legend><p className="mb-3 text-[10px] text-slate-500">{selected.length ? `${selected.length} selected` : `All ${title.toLowerCase()}`}</p><div className="max-h-44 space-y-1 overflow-y-auto pr-1">{items.length ? items.map((item) => <label key={item.id} className="flex cursor-pointer items-start gap-2 rounded-lg p-2 hover:bg-[#fbf5f2]"><input type="checkbox" checked={selectedSet.has(String(item.id))} onChange={() => onChange(selectedSet.has(String(item.id)) ? selected.filter((id) => String(id) !== String(item.id)) : [...selected, item.id])} className="mt-0.5 accent-wine" /><span className="min-w-0"><strong className="block truncate text-xs">{item.label}</strong>{item.subtitle && <small className="block truncate text-[10px] text-slate-400">{item.subtitle}</small>}</span></label>) : <p className="rounded-lg bg-slate-50 p-3 text-xs text-slate-500">No options found.</p>}</div></fieldset>; }
function ChoiceGroup({ label, choices, selected = [], onChange }) { return <fieldset className="rounded-2xl border border-[#e9ddd6] p-4"><legend className="px-1 text-xs font-black">{label}</legend><div className="flex flex-wrap gap-2">{choices.map((choice) => { const active = selected.includes(choice); return <button key={choice} type="button" onClick={() => onChange(active ? selected.filter((item) => item !== choice) : [...selected, choice])} className={`rounded-full border px-3 py-2 text-[10px] font-black ${active ? 'border-wine bg-[#fff2f6] text-wine' : 'border-slate-200 text-slate-500'}`}>{active && <Check size={11} className="mr-1 inline" />}{choice}</button>; })}</div></fieldset>; }
function Field({ label, note, children }) { return <label className="grid min-w-0 gap-2 text-xs font-black"><span>{label}{note && <small className="ml-2 font-normal text-slate-400">{note}</small>}</span><span className="[&>input]:h-12 [&>input]:w-full [&>input]:rounded-xl [&>input]:border [&>input]:border-[#dfd6d0] [&>input]:px-3 [&>input]:text-sm [&>input]:font-normal [&>input]:outline-none [&>input:focus]:border-[#9c5068] [&>select]:h-12 [&>select]:w-full [&>select]:rounded-xl [&>select]:border [&>select]:border-[#dfd6d0] [&>select]:bg-white [&>select]:px-3 [&>select]:text-sm [&>select]:font-normal [&>textarea]:min-h-24 [&>textarea]:w-full [&>textarea]:rounded-xl [&>textarea]:border [&>textarea]:border-[#dfd6d0] [&>textarea]:p-3 [&>textarea]:text-sm [&>textarea]:font-normal [&>textarea]:outline-none">{children}</span></label>; }
function MoneyInput({ value, onChange }) { return <span className="relative block"><span className="absolute left-3 top-3.5 text-sm text-slate-400">Rs.</span><input type="number" min="0" value={value} onChange={(event) => onChange(event.target.value)} className="h-12 w-full rounded-xl border border-[#dfd6d0] pl-10 pr-3 text-sm font-normal outline-none focus:border-[#9c5068]" /></span>; }
function Toggle({ checked, onChange, title, note }) { return <label className="flex cursor-pointer items-start gap-3 rounded-2xl border border-[#e9ddd6] p-4"><input type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)} className="mt-1 h-4 w-4 accent-wine" /><span><strong className="block text-sm">{title}</strong><small className="mt-1 block text-xs leading-5 text-slate-500">{note}</small></span></label>; }
function InfoCard({ icon: Icon, title, text, link, linkLabel }) { return <div className="rounded-2xl border border-[#eaded6] bg-[#fffaf7] p-4"><div className="flex gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-white text-wine"><Icon size={17} /></span><span><strong className="text-sm">{title}</strong><p className="mt-1 text-xs leading-5 text-slate-500">{text}</p>{link && <a href={link} className="mt-2 inline-flex items-center gap-1 text-xs font-black text-wine">{linkLabel} <ArrowRight size={12} /></a>}</span></div></div>; }
function Metric({ icon: Icon, label, value, note }) { return <article className="rounded-[20px] border border-[#eaded6] bg-white p-4 shadow-sm"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f9edf1] text-wine"><Icon size={18} /></span><span><small className="block text-[10px] font-black uppercase tracking-wider text-slate-400">{label}</small><strong className="block text-xl">{value}</strong></span></div><p className="mt-3 text-[10px] font-bold text-slate-400">{note}</p></article>; }
function Mini({ label, value }) { return <div className="min-w-0 px-2 py-3 text-center"><small className="block truncate text-[9px] font-black uppercase tracking-wider text-slate-400">{label}</small><strong className="mt-1 block truncate text-xs text-wine">{value}</strong></div>; }
function SectionTitle({ eyebrow, title, note }) { return <div><p className="text-[10px] font-black uppercase tracking-[0.17em] text-wine">{eyebrow}</p><h2 className="mt-1 font-display text-2xl font-black sm:text-3xl">{title}</h2><p className="mt-1 text-sm leading-6 text-slate-500">{note}</p></div>; }
function ReviewBlock({ title, children }) { return <div className="rounded-2xl border border-[#e9ddd6] p-4"><h3 className="mb-3 text-sm font-black">{title}</h3><div className="grid gap-2">{children}</div></div>; }
function ReviewRow({ label, value }) { return <div className="flex items-start justify-between gap-4 border-b border-slate-100 py-2 last:border-0"><span className="text-xs text-slate-500">{label}</span><strong className="max-w-[65%] text-right text-xs">{value}</strong></div>; }
function Issue({ text, error, success }) { const Icon = error ? XCircle : success ? CheckCircle2 : AlertTriangle; return <p className={`flex items-start gap-2 rounded-xl p-3 text-xs font-bold ${error ? 'bg-rose-50 text-rose-700' : success ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-800'}`}><Icon size={15} className="shrink-0" />{text}</p>; }

function clientReadiness(form) {
  const errors = [];
  const warnings = [];
  const { offer, creative } = form;
  if (!form.name?.trim()) errors.push('Add a campaign name.');
  if (!/^[A-Z0-9_-]{3,32}$/.test(offer.code || '')) errors.push('Add a valid coupon code.');
  if (!creative.image) errors.push('Upload a desktop campaign image.');
  if (offer.benefitType === 'DISCOUNT' && Number(offer.discountValue || 0) <= 0) errors.push('Enter a discount greater than zero.');
  if (form.preset === 'FIRST_ORDER' && (!offer.firstOrderOnly || offer.customerSegment !== 'NEW')) errors.push('First-order campaigns must target new customers and remain first-order only.');
  if (form.preset === 'FIRST_ORDER' && (!Number(offer.minOrderAmount || 0) || !form.endsAt)) errors.push('First-order campaigns need a minimum order and end time.');
  if (form.preset === 'FREE_SHIPPING' && (!Number(offer.minOrderAmount || 0) || !Number(offer.maxDiscountAmount || 0))) errors.push('Free-shipping campaigns need a minimum order and maximum delivery benefit.');
  if (form.preset === 'FESTIVAL' && (!form.endsAt || (!Number(offer.usageLimit || 0) && !Number(offer.totalBudget || 0)))) errors.push('Festival campaigns need an end time and a usage or budget guard.');
  if (form.preset === 'FLASH' && (!form.startsAt || !form.endsAt || new Date(form.endsAt) <= new Date())) errors.push('Flash campaigns need a start time and future end time.');
  if (form.startsAt && form.endsAt && new Date(form.endsAt) <= new Date(form.startsAt)) errors.push('Campaign end must be after its start.');
  if (form.preset === 'CATEGORY' && !offer.applicableCategories.length) errors.push('Choose at least one category.');
  if (offer.benefitType === 'BUY_X_GET_Y' && !offer.applicableProducts.length && !offer.applicableCategories.length) errors.push('Choose products or categories for the buy-and-get offer.');
  if (form.preset === 'REPEAT' && (offer.customerSegment !== 'REPEAT' || Number(offer.minimumPriorOrders || 0) < 1)) errors.push('Repeat-customer campaigns need at least one previous order.');
  if (form.preset === 'VIP' && (offer.customerSegment !== 'VIP' || (!Number(offer.minimumPriorOrders || 0) && !Number(offer.minimumLifetimeSpend || 0)))) errors.push('VIP campaigns need an order-count or lifetime-spend threshold.');
  if (offer.customerSegment === 'SELECTED' && !offer.applicableCustomers.length) errors.push('Choose at least one customer.');
  if (['PRODUCT', 'CATEGORY', 'COLLECTION'].includes(creative.destinationType) && !creative.destinationValue) errors.push('Choose where the banner should open.');
  if (!creative.mobileImage) warnings.push('Add a mobile image for the best phone experience.');
  if (!creative.altText) warnings.push('Add image description text for accessibility.');
  if (!form.endsAt && form.preset !== 'FIRST_ORDER') warnings.push('Add an end time to prevent an offer from remaining live by mistake.');
  if (!Number(offer.usageLimit) && !Number(offer.totalBudget)) warnings.push('Set a usage limit or budget if this offer needs a spending guard.');
  return { errors, warnings };
}
function stepError(step, form) {
  if (!form) return '';
  if (step === 0 && form.name.trim().length < 3) return 'Enter a campaign name with at least 3 characters.';
  if (step === 1 && form.preset === 'CATEGORY' && !form.offer.applicableCategories.length) return 'Choose at least one category for this campaign.';
  if (step === 1 && form.offer.benefitType === 'BUY_X_GET_Y' && !form.offer.applicableProducts.length && !form.offer.applicableCategories.length) return 'Choose eligible products or categories for this buy-and-get offer.';
  if (step === 1 && form.offer.customerSegment === 'SELECTED' && !form.offer.applicableCustomers.length) return 'Choose the customers who should receive this offer.';
  if (step === 1 && form.preset === 'REPEAT' && Number(form.offer.minimumPriorOrders || 0) < 1) return 'Set at least one previous order for repeat customers.';
  if (step === 1 && form.preset === 'VIP' && !Number(form.offer.minimumPriorOrders || 0) && !Number(form.offer.minimumLifetimeSpend || 0)) return 'Set an order or lifetime-spend threshold for VIP customers.';
  if (step === 2 && !/^[A-Z0-9_-]{3,32}$/.test(form.offer.code || '')) return 'Enter a valid coupon code.';
  if (step === 2 && form.offer.benefitType === 'DISCOUNT' && Number(form.offer.discountValue || 0) <= 0) return 'Enter a discount greater than zero.';
  if (step === 2 && form.preset === 'FIRST_ORDER' && !Number(form.offer.minOrderAmount || 0)) return 'Set a minimum order for this first-order offer.';
  if (step === 2 && form.preset === 'FREE_SHIPPING' && (!Number(form.offer.minOrderAmount || 0) || !Number(form.offer.maxDiscountAmount || 0))) return 'Set a minimum order and maximum delivery benefit.';
  if (step === 3 && !form.creative.image) return 'Upload the desktop campaign image.';
  if (step === 4 && form.startsAt && form.endsAt && new Date(form.endsAt) <= new Date(form.startsAt)) return 'Campaign end must be after its start.';
  if (step === 4 && form.preset === 'FLASH' && (!form.startsAt || !form.endsAt || new Date(form.endsAt) <= new Date())) return 'Flash campaigns need a start time and future end time.';
  if (step === 4 && form.preset === 'FESTIVAL' && (!form.endsAt || (!Number(form.offer.usageLimit || 0) && !Number(form.offer.totalBudget || 0)))) return 'Festival campaigns need an end time and a usage or budget guard.';
  return '';
}
function payload(form, publish) { return { idempotencyKey: form.idempotencyKey, name: form.name, preset: form.preset, startsAt: toIso(form.startsAt), endsAt: toIso(form.endsAt), timezone: form.timezone, offer: form.offer, creative: form.creative, revision: form.revision, publish }; }
function toForm(campaign) { return { _id: campaign._id, state: campaign.state, revision: campaign.revision || 0, idempotencyKey: campaign.idempotencyKey || '', name: campaign.name || '', preset: campaign.preset || 'FESTIVAL', startsAt: localDateTime(campaign.startsAt), endsAt: localDateTime(campaign.endsAt), timezone: campaign.timezone || 'Asia/Kolkata', offer: { ...initialForm(campaign.preset).offer, ...(campaign.offer || {}), applicableProducts: ids(campaign.offer?.applicableProducts), applicableCategories: ids(campaign.offer?.applicableCategories), applicableCustomers: ids(campaign.offer?.applicableCustomers) }, creative: { ...initialForm(campaign.preset).creative, ...(campaign.creative || {}) } }; }
function ids(value) { return (value || []).map((item) => String(item?._id || item)); }
function statusTone(status) { if (status === 'Live') return 'bg-emerald-100 text-emerald-800'; if (status === 'Scheduled') return 'bg-blue-100 text-blue-800'; if (status === 'Failed') return 'bg-rose-100 text-rose-800'; if (status === 'Ended') return 'bg-amber-100 text-amber-800'; return 'bg-slate-100 text-slate-600'; }
function scheduleLabel(form) { const starts = form.startsAt ? formatDate(form.startsAt) : 'When published'; const ends = form.endsAt ? formatDate(form.endsAt) : 'No end time'; return `${starts} to ${ends}`; }
function offerLabel(offer = {}) { if (offer.benefitType === 'FREE_SHIPPING') return `Free shipping${Number(offer.minOrderAmount) ? ` above Rs. ${money(offer.minOrderAmount)}` : ''}`; if (offer.benefitType === 'BUY_X_GET_Y') return `Buy ${offer.buyQuantity || 2}, get ${offer.getQuantity || 1}`; return offer.type === 'Flat' ? `Rs. ${money(offer.discountValue)} off` : `${number(offer.discountValue)}% off`; }
function actionMessage(action) { return ({ PUBLISH: 'Campaign published and linked records synchronized.', PAUSE: 'Campaign paused across the storefront and checkout.', ARCHIVE: 'Campaign archived with its history preserved.', RESTORE: 'Campaign restored as paused.', DUPLICATE: 'A safe draft copy was created.', REPAIR: 'Campaign links repaired and published.' })[action] || 'Campaign updated.'; }
function titleCase(value) { return String(value || '').toLowerCase().replace(/(^|[_\s-])\w/g, (letter) => letter.toUpperCase()).replace(/_/g, ' '); }
function codeFrom(value) { return String(value || '').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 32); }
function localDateTime(value) { if (!value) return ''; const date = new Date(value); if (Number.isNaN(date.getTime())) return ''; const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return local.toISOString().slice(0, 16); }
function toIso(value) { if (!value) return null; const date = new Date(value); return Number.isNaN(date.getTime()) ? null : date.toISOString(); }
function formatDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Not set' : date.toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' }); }
function money(value) { return Number(value || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 }); }
function compactMoney(value) { const amount = Number(value || 0); return amount >= 100000 ? `${(amount / 100000).toFixed(1)}L` : amount >= 1000 ? `${(amount / 1000).toFixed(1)}K` : money(amount); }

export { initialForm as buildInitialCampaign };
function number(value) { return Number(value || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 }); }
